<?php if($reverseSource['original']):$reverseOriginalRow=$reverseSource['original']; ?><p><strong><?= $reverseE('Ursprüngliche Zahlung:') ?></strong> <?= e(dateDe($reverseOriginalRow['booked_on']).' · '.$reverseOriginalRow['account_name'].' · '.euro((int)$reverseOriginalRow['cents'])) ?></p><p><a class="btn btn-outline theme-secondary" href="<?= e(url(bankTransactionContext($reverseOriginalRow['id'],$_GET))) ?>" target="_blank" rel="noopener"><?= $reverseE('Ursprünglichen Kontoumsatz öffnen') ?></a></p><?php endif ?>
